package witchinggadgets;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
import net.minecraft.core.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.GameType;
import thaumcraft.research.ResearchCategories;
@GameTestHolder(WitchingGadgets.ID) @PrefixGameTestTemplate(false)
public final class Port3Tests {
    @GameTest(template="test/platform") public static void originalResearchIconsSurvive(GameTestHelper h){for(String key:java.util.List.of("ENCH_INVISIBLEGEAR","ENCH_UNVEILING","ENCH_STEALTH","ENCH_BACKSTAB","ENCH_RIDEPROTECT","PRIMORDIALARMOR","PRIMORDIALWEAPONRY","METALLURGICPERFECTION_CLUSTERS"))h.assertTrue(ResearchCategories.getResearch(key).iconTexture()!=null,"texture icon replaced with unrelated item: "+key);h.assertTrue(ResearchCategories.getResearch("WGFAKEINFUSIONENCHANTMENT").iconTexture().toString().equals("thaumcraft:textures/misc/r_enchant.png"),"WG proxy lost its explicitly specified legacy icon");h.assertTrue(ResearchCategories.getResearch("WGFAKEPRIMPEARL").iconItem().create().is(Content.tc("primordial_pearl")),"WG pearl proxy must use its item icon");h.succeed();}
    @GameTest(template="test/platform") public static void focusRecipesMatchOriginalComponents(GameTestHelper h){int count=0;for(var e:PortData.read("recipes")){var o=e.getAsJsonObject();if(o.has("output")&&PortData.str(o.getAsJsonObject("output"),"id").startsWith("witchinggadgets:focus_")){count++;var ingredients=new java.util.ArrayList<com.google.gson.JsonObject>();if(o.has("symbols"))o.getAsJsonObject("symbols").entrySet().forEach(e2->ingredients.add(e2.getValue().getAsJsonObject()));if(o.has("ingredients"))o.getAsJsonArray("ingredients").forEach(e2->ingredients.add(e2.getAsJsonObject()));boolean tube=false;for(var ingredient:ingredients){String id=PortData.str(ingredient,"id");h.assertTrue(!id.equals("minecraft:slime_ball")&&!id.equals("thaumcraft:warded_jar"),"new focus model changed the original ingredients");tube|=id.equals("thaumcraft:essentia_tube");}h.assertTrue(tube,"focus lacks its original tube");}}h.assertValueEqual(count,7,"focus recipes missing");h.succeed();}
    @GameTest(template="test/platform") public static void roseSelectionMatchesCompactFloorBranches(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(pos,Content.block("rose_vines").defaultBlockState());var m=(MachineEntity)h.getLevel().getBlockEntity(pos);m.progress=5;var shape=RoseGeometry.shape(h.getLevel(),pos);h.assertTrue(shape.bounds().maxY<=.375,"floor vines have a full-height hitbox");h.assertTrue(Content.block("rose_vines").defaultBlockState().getCollisionShape(h.getLevel(),pos).isEmpty(),"vines block player movement");h.succeed();}
    @GameTest(template="test/platform") public static void restoredMenusKeepSlotCountsAndPositions(GameTestHelper h){var p=h.makeMockPlayer(GameType.SURVIVAL);for(String kind:java.util.List.of("spinning_wheel","cutting_table","label_library")){var m=new MachineEntity(BlockPos.ZERO,Content.block(kind).defaultBlockState());var menu=new MachineMenu(1,p.getInventory(),m);h.assertValueEqual(menu.slots.size(),36+menu.count,"inventory slots lost");h.assertValueEqual(menu.slots.get(0).x,kind.equals("spinning_wheel")?16:kind.equals("cutting_table")?42:8,"input slot misaligned with original GUI");}h.succeed();}
    @GameTest(template="test/platform") public static void gloveMenuHasFiveRealGemSockets(GameTestHelper h){var p=h.makeMockPlayer(GameType.SURVIVAL);var glove=Content.stack("primordial_gauntlet");var storage=new BagItem.Storage(glove,9);var menu=new StorageMenu(1,p.getInventory(),glove,storage,9);h.assertValueEqual(menu.count,5,"inactive sockets exposed");h.assertValueEqual(menu.slots.size(),41,"glove slot count");h.assertTrue(!menu.slots.get(0).mayPlace(new ItemStack(Items.DIAMOND)),"ordinary item accepted as a gem");h.assertValueEqual(menu.slots.get(4).x,103,"glove socket offset");h.succeed();}
    @GameTest(template="test/platform") public static void storageMenuShiftClickPersistsAndRejectsNestedBags(GameTestHelper h){var p=h.makeMockPlayer(GameType.SURVIVAL);var bag=Content.stack("bag_of_tricks");var storage=new BagItem.Storage(bag,18);var menu=new StorageMenu(1,p.getInventory(),bag,storage,18);p.getInventory().setItem(9,new ItemStack(Items.DIAMOND,7));menu.quickMoveStack(p,18);h.assertValueEqual(new BagItem.Storage(bag.copy(),18).getItem(0).getCount(),7,"shift-click was not saved to item components");h.assertTrue(!menu.slots.get(0).mayPlace(Content.stack("bag_of_tricks")),"nested bag accepted");h.succeed();}
}
